const config = {
  "previewFeatures": [],
  "clientVersion": "7.4.0",
  "engineVersion": "ab56fe763f921d033a6c195e7ddeb3e255bdbb57",
  "activeProvider": "postgresql",
  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum Currency {\n  AFN\n  EUR\n  ALL\n  DZD\n  USD\n  AOA\n  XCD\n  ARS\n  AMD\n  AWG\n  AUD\n  AZN\n  BSD\n  BHD\n  BDT\n  BBD\n  BYN\n  BZD\n  XOF\n  BMD\n  INR\n  BTN\n  BOB\n  BOV\n  BAM\n  BWP\n  NOK\n  BRL\n  BND\n  BGN\n  BIF\n  CVE\n  KHR\n  XAF\n  CAD\n  KYD\n  CLP\n  CLF\n  CNY\n  COP\n  COU\n  KMF\n  CDF\n  NZD\n  CRC\n  HRK\n  CUP\n  CUC\n  ANG\n  CZK\n  DKK\n  DJF\n  DOP\n  EGP\n  SVC\n  ERN\n  ETB\n  FKP\n  FJD\n  XPF\n  GMD\n  GEL\n  GHS\n  GIP\n  GTQ\n  GBP\n  GNF\n  GYD\n  HTG\n  HNL\n  HKD\n  HUF\n  ISK\n  IDR\n  XDR\n  IRR\n  IQD\n  ILS\n  JMD\n  JPY\n  JOD\n  KZT\n  KES\n  KPW\n  KRW\n  KWD\n  KGS\n  LAK\n  LBP\n  LSL\n  ZAR\n  LRD\n  LYD\n  CHF\n  MOP\n  MKD\n  MGA\n  MWK\n  MYR\n  MVR\n  MUR\n  XUA\n  MXN\n  MXV\n  MDL\n  MNT\n  MAD\n  MZN\n  MMK\n  NAD\n  NPR\n  NIO\n  NGN\n  OMR\n  PKR\n  PAB\n  PGK\n  PYG\n  PEN\n  PHP\n  PLN\n  QAR\n  RON\n  RUB\n  RWF\n  SHP\n  WST\n  STN\n  SAR\n  RSD\n  SCR\n  SLL\n  SGD\n  XSU\n  SBD\n  SOS\n  SSP\n  LKR\n  SDG\n  SRD\n  SZL\n  SEK\n  CHE\n  CHW\n  SYP\n  TWD\n  TJS\n  TZS\n  THB\n  TOP\n  TTD\n  TND\n  TRY\n  TMT\n  UGX\n  UAH\n  AED\n  USN\n  UYU\n  UYI\n  UYW\n  UZS\n  VUV\n  VES\n  VND\n  XBA\n  XBB\n  XBC\n  XBD\n  XTS\n  XXX\n  XAU\n  XPD\n  XPT\n  XAG\n  ZMW\n  ZWL\n}\n\nmodel Currencies {\n  id       String   @id @default(cuid())\n  currency Currency\n  label    String\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nenum Language {\n  // Core “base” languages\n  EN // en\n  FR // fr\n  ES // es\n  PT // pt\n\n  // Key English variants\n  EN_US // en-US\n  EN_GB // en-GB\n\n  // Important regional languages for NG/Africa\n  HA_LATN_NG // ha-Latn-NG\n  YO_NG // yo-NG\n  IG_NG // ig-NG\n  SW_KE // sw-KE\n  SW_TZ // sw-TZ\n}\n\nmodel Locale {\n  id       String   @id @default(cuid())\n  language Language\n  label    String\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nenum DateFormat {\n  DMY\n  MDY\n  YMD\n}\n\nmodel User {\n  id              String    @id @default(cuid())\n  email           String    @unique\n  password        String?\n  loginAttempts   Int       @default(0)\n  emailVerified   Boolean   @default(false)\n  emailVerifiedAt DateTime?\n  firstName       String\n  lastName        String\n  avatar          String?\n  lastLoginAt     DateTime?\n\n  // 2FA fields\n  twoFactorAttempts   Int       @default(0)\n  twoFactorEnabled    Boolean   @default(false)\n  twoFactorSecret     String? // base32 TOTP secret, null until setup initiated => Encrypted\n  twoFactorLastUsedAt DateTime?\n  hasSeenTwoFaPrompt  Boolean   @default(false)\n\n  // onboarding\n  hasCompletedOnboarding Boolean @default(false)\n\n  // preferences\n  currency   Currency   @default(NGN)\n  language   Language   @default(EN_US)\n  timezone   String     @default(\"Africa/Lagos\")\n  dateFormat DateFormat @default(DMY)\n\n  // reverse relationship\n  accounts                  Account[]\n  sessions                  Session[]\n  subscription              Subscription?\n  usageTrackers             UsageTracker[]\n  backupCodes               BackupCodes[]\n  loginActivity             LoginActivity[]\n  setting                   NotificationSetting?\n  categories                Category[]\n  transactions              Transaction[]\n  budgets                   Budget[]\n  recurringItems            RecurringItem[]\n  goals                     Goal[]\n  splits                    Split[]\n  ocrDrafts                 OCRDraft[]\n  fcmDevices                FcmDevice[]\n  activityLogs              ActivityLogs[]\n  monoBankAccounts          MonoBankAccount[]\n  notifications             Notification[]\n  classificationCorrections ClassificationCorrection[]\n  userBalance               UserBalance?\n  monthlyBalanceSnapshots   MonthlyBalanceSnapshot[]\n  analyticsSnapshots        AnalyticsSnapshot[]\n  aiInsights                AiInsight[]\n\n  // account deletion\n  scheduledDeletionAt DateTime?\n\n  // time stamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nenum AccountType {\n  OAUTH\n  OIDC\n  CREDENTIALS\n}\n\nenum AccountProvider {\n  GOOGLE\n  GITHUB\n  APPLE\n  LOCAL\n}\n\nmodel Account {\n  id                String          @id @default(cuid())\n  userId            String\n  type              AccountType\n  provider          AccountProvider\n  providerAccountId String\n  refreshToken      String?         @db.Text\n  accessToken       String?         @db.Text\n  expiresAt         Int?\n  user              User            @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // time stamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([provider, providerAccountId])\n  @@index([userId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n  deviceId     String\n  userAgent    String?\n  ipAddress    String?\n  location     String?\n  lastUsedAt   DateTime @default(now())\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // time stamps\n  createdAt DateTime @default(now())\n\n  @@unique([userId, deviceId])\n}\n\nenum LoginActivityType {\n  PASSWORD\n  MFA\n}\n\nenum LoginActivityStatus {\n  FALED\n  SUCCESS\n}\n\nmodel LoginActivity {\n  id        String              @id @default(cuid())\n  type      LoginActivityType\n  status    LoginActivityStatus\n  deviceId  String\n  userAgent String?\n  ipAddress String?\n  location  String?\n\n  // foreign relationships\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // time stamps\n  createdAt DateTime @default(now())\n\n  @@index([userId, createdAt])\n}\n\nenum VerificationIdentifier {\n  PASSWORD\n  EMAIL\n  RESET\n  EMAIL_CHANGE\n}\n\nmodel VerificationToken {\n  id         String                 @id @default(cuid())\n  identifier VerificationIdentifier\n  email      String\n  token      String\n  newEmail   String? // pending target email, used only for EMAIL_CHANGE flows\n  expires    DateTime\n\n  // time stamps\n  createdAt DateTime @default(now())\n\n  @@unique([email, token, identifier])\n}\n\nenum SubscriptionPlan {\n  FREE\n  PRO\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  NON_RENEWING\n  ATTENTION\n  COMPLETED\n  CANCELLED\n}\n\nmodel Subscription {\n  id                         String             @id @default(cuid())\n  userId                     String             @unique\n  user                       User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  paystackCustomerCode       String?            @unique\n  paystackSubscriptionCode   String?            @unique\n  paystackAuthorizationCode  String? // AUTH_xxxx — card token, NOT the card (encrypted at rest via EncryptionService)\n  paystackEmailToken         String? // required by Paystack for /subscription disable|enable (encrypted at rest via EncryptionService)\n  paystackPlanCode           String?\n  paystackCurrentPeriodStart DateTime?\n  paystackCurrentPeriodEnd   DateTime?\n  paystackCancelAtPeriodEnd  Boolean            @default(false)\n  status                     SubscriptionStatus @default(ACTIVE)\n  plan                       SubscriptionPlan   @default(FREE)\n\n  // timstamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel SusbcriptionFreeTrials {\n  id String @id @default(cuid())\n\n  // Abuse guard: sha256(lowercase(trim(email))). Stable across account deletion +\n  // re-registration, and not reversible PII — so a deleted user cannot re-trial.\n  emailHash String @unique\n\n  // Soft references for support/debugging only — NOT the eligibility key, and\n  // intentionally not an onDelete-cascade relation. Nullable so account deletion\n  // can detach the row while keeping the guard.\n  userId         String?\n  subscriptionId String?\n\n  trialStartsAt DateTime\n  trialEndsAt   DateTime?\n\n  // timstamps\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel PaystackWebhookEvent {\n  id          String   @id @default(cuid())\n  eventId     String   @unique // Paystack event.id\n  eventType   String\n  processedAt DateTime @default(now())\n}\n\nenum UsageFeature {\n  AI_INSIGHTS_QUERIES\n  AI_CHAT_MESSAGES\n  RECEIPT_UPLOADS\n}\n\nmodel UsageTracker {\n  id          String       @id @default(cuid())\n  userId      String\n  user        User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  feature     UsageFeature\n  count       Int          @default(0)\n  periodStart DateTime // First day of current month (UTC midnight)\n  periodEnd   DateTime // First day of next month (UTC midnight)\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  @@unique([userId, feature, periodStart])\n  @@index([userId, feature])\n}\n\nmodel UserBalance {\n  id String @id @default(cuid())\n\n  netBalance     Decimal @default(0) @db.Decimal(20, 2)\n  totalIncome    Decimal @default(0) @db.Decimal(20, 2)\n  totalExpense   Decimal @default(0) @db.Decimal(20, 2)\n  monthlyIncome  Decimal @default(0) @db.Decimal(20, 2)\n  monthlyExpense Decimal @default(0) @db.Decimal(20, 2)\n  monthYear      String // \"YYYY-MM\" — which month the monthly counters belong to\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel MonthlyBalanceSnapshot {\n  id String @id @default(cuid())\n\n  monthYear String // \"YYYY-MM\"\n  income    Decimal @db.Decimal(20, 2)\n  expense   Decimal @db.Decimal(20, 2)\n  net       Decimal @db.Decimal(20, 2)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, monthYear])\n}\n\nmodel BackupCodes {\n  id     String    @id @default(cuid())\n  usedAt DateTime?\n  code   String // Hashed Code For Security, Contains the secret andiv as secret:iv\n  userId String\n  user   User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([userId, usedAt])\n}\n\nmodel ActivityLogs {\n  id         String @id @default(cuid())\n  event      String // transaction.created, budget.created, goal.created, split.created, etc.\n  entityId   String\n  entityType String // transaction, budget, goal, split, etc.\n  data       Json //{source: \"manual\", sourceId: \"123\", old: {amount: 100, date: \"2021-01-01\"}, new: {amount: 200, date: \"2021-01-01\"}} depnds on the event, transaction data are encoded in the data field\n\n  // relationships\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // timestamp\n  createdAt DateTime @default(now())\n\n  @@index([userId, createdAt])\n}\n\nmodel NotificationSetting {\n  id String @id @default(cuid())\n\n  // budget alerts\n  budgetAlertMail Boolean @default(true)\n  budgetAlertApp  Boolean @default(true)\n\n  // reminders\n  billReminderMail Boolean @default(true)\n  billReminderApp  Boolean @default(true)\n\n  // weekly reports\n  weeklyReportMail Boolean @default(true)\n  weeklyReportApp  Boolean @default(true)\n\n  // ai insights\n  aiInsightsMail Boolean @default(true)\n  aiInsightsApp  Boolean @default(true)\n\n  // goals\n  goalsAlertMail Boolean @default(true)\n  goalsAlertApp  Boolean @default(true)\n\n  // splits\n  splitsAlertMail Boolean @default(true)\n  splitsAlertApp  Boolean @default(true)\n\n  //news letter\n  newsLetterAlert Boolean @default(false)\n\n  // community updates\n  communityAlert Boolean @default(false)\n\n  // Allow Users to gate daily insights\n  dailyInsightsEnabled Boolean @default(true)\n\n  // relations\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Category {\n  id          String   @id @default(cuid())\n  name        String\n  slug        String   @unique\n  description String?\n  icon        String?\n  color       String?\n  isSystem    Boolean  @default(false) // true = generic, false = user-created\n  tags        String[] @default([])\n\n  // nullable relation — null means it's a system/generic category\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // relations\n  transactions   Transaction[]\n  budgets        Budget[]\n  recurringItems RecurringItem[]\n\n  @@unique([name, userId]) // prevents duplicate names per user, but allows\n  // same name across different users or system\n  @@index([userId])\n  @@index([isSystem])\n}\n\nmodel Merchant {\n  id           String   @id @default(cuid())\n  name         String   @unique // canonical name, uppercase — \"KFC\"\n  aliases      String[] // alternate narration fragments — [\"KENTUCKY\", \"K F C\"]\n  categoryHint String // space-separated hint tokens — \"food restaurant fast\"\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nenum BudgetPeriod {\n  MONTHLY\n  WEEKLY\n  QUARTERLY\n  YEARLY\n}\n\nmodel Budget {\n  id               String       @id @default(cuid())\n  name             String\n  amount           Float\n  description      String?\n  period           BudgetPeriod @default(MONTHLY)\n  carryOver        Boolean      @default(false) // will always be false for V1\n  alertThreshold   Float        @default(0.8) // 80% of budget\n  alertedAt        DateTime?\n  alertAtFrequency Int          @default(2)\n  deactivatedAt    DateTime? // track soft delete of budget from an onset\n\n  // classification\n  categoryId String\n  category   Category @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  // ownership\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // relationships\n  budgetHistory BudgetHistory[]\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, categoryId, period])\n}\n\n// SCD => Slowly Changing Dimension Tracking Limit changes over time\nmodel BudgetHistory {\n  id        String    @id @default(cuid())\n  limit     Float\n  startDate DateTime\n  endDate   DateTime?\n\n  // relationships\n  budgetId String\n  budget   Budget @relation(fields: [budgetId], references: [id], onDelete: Cascade)\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([budgetId, startDate])\n}\n\nenum OCRDraftStatus {\n  PENDING\n  PROCESSING\n  COMPLETED\n  FAILED\n}\n\nmodel OCRDraft {\n  id            String         @id @default(cuid())\n  amount        Float?\n  date          DateTime?\n  description   String?\n  notes         String?\n  merchant      String?\n  imageKey      String         @unique\n  status        OCRDraftStatus @default(PENDING)\n  confidence    Float?\n  faliureReason String?\n  rawData       Json?\n  confirmedAt   DateTime?\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, status])\n  @@index([userId, imageKey])\n}\n\nenum TransactionType {\n  INCOME\n  EXPENSE\n}\n\nenum TransactionSource {\n  MANUAL\n  BANK\n  RECURRING\n  OCR\n  SPLIT\n}\n\nenum BankTransactionStatus {\n  PENDING\n  COMPLETED\n  FAILED\n}\n\nmodel Transaction {\n  id           String          @id @default(cuid())\n  amount       Float\n  date         DateTime\n  type         TransactionType\n  description  String?\n  narration    String? // raw bank narration from Mono — immutable, never user-edited; null for manual transactions\n  bankCategory String? // raw Mono category enum (e.g. \"food_and_drinks\") — stored for AI classification; null for manual transactions\n  notes        String?\n  merchant     String? // merchant name picked from merchant or typed in by user\n\n  // vector embedding on transaction for semantic retrieval\n  embedding Unsupported(\"vector(1536)\")?\n\n  // classification\n  categoryId String\n  category   Category @relation(fields: [categoryId], references: [id], onDelete: Restrict)\n\n  // ownership\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  // source metadata\n  source     TransactionSource @default(MANUAL)\n  sourceId   String // Human-readable reference: TXN-YYMMDD-XXXXXX / REC-YYMMDD-XXXXXX / BNK-YYMMDD-XXXXXX\n  sourceData Json? // JSON blob for OCR/Split/mono/etc. metadata\n\n  // mono bank data\n  bankTransactionId     String? // Mono's original transaction ID — used for idempotency on bank sync\n  bankTransactionStatus BankTransactionStatus @default(COMPLETED) // Only Completed transactions are supported in V1\n\n  // recurring link — set for transactions created by the scheduler from a RecurringItem\n  recurringItemId String?\n  recurringItem   RecurringItem? @relation(fields: [recurringItemId], references: [id], onDelete: SetNull)\n\n  // relations\n  split            Split?\n  goalContribution GoalContribution?\n  settlements      SplitSettlement[]\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  aiClassified Boolean @default(false)\n\n  monoBankAccountId String? // bank account this transaction belongs to\n  monoBankAccount   MonoBankAccount? @relation(fields: [monoBankAccountId], references: [id], onDelete: SetNull)\n\n  @@unique([userId, source, sourceId])\n  @@unique([userId, bankTransactionId, monoBankAccountId])\n  @@index([userId, date])\n  @@index([userId, source, date])\n  @@index([userId, categoryId, date])\n  @@index([userId, sourceId])\n  @@index([monoBankAccountId, bankTransactionId]) // ensure idempotency\n}\n\nenum RecurringItemFrequency {\n  DAILY\n  WEEKLY\n  BIWEEKLY\n  MONTHLY\n  QUARTERLY\n  YEARLY\n  CUSTOM\n}\n\nmodel RecurringItem {\n  id          String                 @id @default(cuid())\n  name        String\n  amount      Float\n  type        TransactionType\n  frequency   RecurringItemFrequency\n  startDate   DateTime\n  endDate     DateTime?\n  description String?\n  notes       String?\n  merchant    String?\n\n  // trackers\n  lastRunAt DateTime? // null if never run\n  nextRunAt DateTime\n  isActive  Boolean   @default(true)\n\n  // classification\n  categoryId String\n  category   Category @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  // ownership\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // transactions created by this recurring item\n  transactions Transaction[]\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, isActive])\n  @@index([isActive, nextRunAt])\n}\n\nenum Goalstatus {\n  ACTIVE\n  COMPLETED\n  ON_HOLD\n}\n\nenum GoalPriority {\n  LOW\n  MEDIUM\n  HIGH\n}\n\nmodel Goal {\n  id           String     @id @default(cuid())\n  name         String\n  targetAmount Float\n  targetDate   DateTime\n  status       Goalstatus @default(ACTIVE)\n  description  String?\n\n  priority GoalPriority @default(MEDIUM)\n\n  // owner\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // relationships\n  contributions GoalContribution[]\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, status])\n}\n\nmodel GoalContribution {\n  id          String   @id @default(cuid())\n  amount      Float\n  date        DateTime\n  description String?\n  notes       String?\n\n  // relationship\n  goalId        String\n  goal          Goal         @relation(fields: [goalId], references: [id], onDelete: Cascade)\n  transactionId String?      @unique\n  transaction   Transaction? @relation(fields: [transactionId], references: [id], onDelete: Cascade) // goal contribution transaction can only be expense transaction\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([goalId])\n}\n\nenum SplitStatus {\n  OPEN\n  PARTIALLY_SETTLED\n  SETTLED\n}\n\nmodel Split {\n  id     String      @id @default(cuid())\n  name   String\n  amount Float\n  status SplitStatus @default(OPEN)\n\n  // ownership\n  userId        String\n  user          User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  transactionId String?      @unique\n  transaction   Transaction? @relation(fields: [transactionId], references: [id], onDelete: Restrict)\n\n  // relationships\n  participants SplitParticipant[]\n  settlements  SplitSettlement[]\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, name])\n  @@index([userId, status])\n}\n\nmodel SplitParticipant {\n  id     String @id @default(cuid())\n  name   String\n  email  String\n  amount Float\n\n  // relationships\n  splitId String\n  split   Split  @relation(fields: [splitId], references: [id], onDelete: Cascade)\n\n  settlements SplitSettlement[]\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel SplitSettlement {\n  id         String   @id @default(cuid())\n  paidAt     DateTime\n  paidAmount Float\n\n  // relationships\n  splitId       String\n  split         Split            @relation(fields: [splitId], references: [id], onDelete: Cascade)\n  participantId String\n  participant   SplitParticipant @relation(fields: [participantId], references: [id], onDelete: Cascade)\n  transactionId String?          @unique\n  transaction   Transaction?     @relation(fields: [transactionId], references: [id], onDelete: Cascade) // split settlement transaction can only be income transaction\n\n  // timestamp\n  createdAt DateTime @default(now())\n}\n\nenum MonoBankAccountStatus {\n  AVAILABLE\n  PARTIAL\n  UNAVAILABLE\n  PROCESSING\n}\n\nmodel MonoBankAccount {\n  id              String                @id @default(cuid())\n  accountId       String                @unique\n  bankId          String\n  bankName        String\n  accountNumber   String\n  accountName     String\n  accountType     String\n  accountBalance  String\n  accountCurrency Currency\n  status          MonoBankAccountStatus\n  lastSyncedAt    DateTime?\n  isDefault       Boolean               @default(false)\n\n  // ownership\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // relationships\n  transactions Transaction[]\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, accountId])\n  @@index([userId, accountNumber])\n}\n\nmodel FcmDevice {\n  id       String @id @default(cuid())\n  fcmToken String\n\n  //relations\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, fcmToken])\n}\n\nmodel Notification {\n  id             String    @id @default(cuid())\n  title          String\n  body           String\n  data           Json?\n  readAt         DateTime?\n  read           Boolean   @default(false)\n  archivedAt     DateTime?\n  archived       Boolean   @default(false)\n  notificationId String    @unique\n\n  // ownership\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // timestamp\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, archived, createdAt])\n}\n\nmodel ClassificationCorrection {\n  id            String @id @default(cuid())\n  narration     String // raw Mono narration text that was corrected\n  correctedSlug String // the category slug the user switched to\n\n  // vector embedding of the narration — nullable until the async BullMQ worker processes it\n  embedding Unsupported(\"vector(1536)\")?\n\n  // ownership — cascade delete ensures corrections are removed when user is deleted\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // timestamp\n  createdAt DateTime @default(now())\n\n  @@unique([userId, narration])\n  @@index([userId])\n}\n\nenum SnapshotType {\n  MONTHLY_SUMMARY\n  QUARTERLY_SUMMARY\n  YEARLY_SUMMARY\n}\n\nenum InsightTrigger {\n  DAILY\n  BUDGET_BREACH\n  MANUAL\n}\n\nenum InsightSeverity {\n  INFO\n  WARNING\n  CRITICAL\n}\n\nmodel AnalyticsSnapshot {\n  id         String       @id @default(cuid())\n  userId     String\n  user       User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  period     String // \"YYYY-MM\"\n  type       SnapshotType\n  data       Json\n  computedAt DateTime     @default(now())\n\n  @@unique([userId, period, type])\n  @@index([userId, period])\n}\n\nmodel AiInsight {\n  id                   String          @id @default(cuid())\n  userId               String\n  user                 User            @relation(fields: [userId], references: [id], onDelete: Cascade)\n  generatedAt          DateTime        @default(now())\n  trigger              InsightTrigger\n  severity             InsightSeverity\n  summary              String\n  anomalies            Json            @default(\"[]\")\n  goalAlerts           Json            @default(\"[]\")\n  cashFlowForecast     String?\n  recommendations      Json            @default(\"[]\")\n  macroContext         Json            @default(\"{}\")\n  budgetBreach         Json            @default(\"[]\")\n  conversationThreadId String?\n  readAt               DateTime?\n  notifiedAt           DateTime?\n  createdAt            DateTime        @default(now())\n  updatedAt            DateTime        @updatedAt\n\n  @@index([userId, generatedAt(sort: Desc)])\n}\n"
}

